import {retirementComparisonHTML}from './retirement-diagnostics.mjs';
import {REVISION126_SOURCES}from './revision126-data.mjs';
import {REVISION126_CHECKS as checks}from './revision126-validation-data.mjs';
import {growthDiagnostics}from './dynamics-diagnostics.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(x,d=2)=>Number.isFinite(x)?x.toLocaleString('en-GB',{minimumFractionDigits:d,maximumFractionDigits:d}):'Unavailable';
export function revision126SourceHTML(code){const b=REVISION126_SOURCES[code];if(!b)return '';const r=b.retirement,p=b.population,f=b.foreign,i=b.income;
 return `<section class="panel content-panel"><div class="eyebrow">POPULATION, INCOME AND INTERNATIONAL FINANCE · ENGINE 1.26</div><h2>Source definitions that change the result.</h2><p class="small muted">${checks.paths} paired/comparison and policy paths · ${n(checks.years,0)} annual steps passed accounting checks. Forecast diagnostic for 29 countries: GDP growth RMSE ${n(checks.countries.gdp.earlier.RMSE)} → ${n(checks.countries.gdp.candidate.RMSE)} points; current-account RMSE ${n(checks.countries.ca.earlier.RMSE)} → ${n(checks.countries.ca.candidate.RMSE)} points. The results are mixed, using previously examined 2024/25 data. Passing accounting checks does not establish forecast accuracy. The overlapping EU aggregate is scored separately in the full report.</p><details open><summary>Age composition and pension eligibility · ${esc(p.name)}</summary><p>Population reference: ${esc(p.referenceDate)} · ${esc(p.ageResolution)}. Age cohorts advance one year at a time. Children, people aged 15–64 and people aged 65+ are tracked separately; their shares can change.</p><p><strong>Opening pension reference: ${n(r.representativeAge)} years.</strong> Male/female source references: ${n(r.maleAge)} / ${n(r.femaleAge)}. ${esc(r.representativeMethod)} Pension eligibility is distinct from actual labour-force exit. The editable pension age affects participation and benefits; reaching it does not force every person out of work.</p><p class="small muted">Births, mortality and migration affect cohorts. Future mortality within broad age groups, migrant age/skill allocation, and future policy responses remain labelled assumptions or proxies. European older-age participation uses the observed 65+/15–64 activity ratio; the USA and China use separately retained ILOSTAT published estimates for the same age bands. The pension-reform response is a separate, unestimated assumption. China uses uniform allocation inside observed five-year bands and retains an open 80+ group; it does not invent a detailed oldest-age profile. Future statutory reforms require an explicit timeline; the 2023 reference is not a claim about every future law.</p><a href="${esc(p.url)}" target="_blank" rel="noreferrer">Population source ↗</a> · <a href="${esc(r.url)}" target="_blank" rel="noreferrer">Pension-age source and conditions ↗</a></details>
 <details><summary>Labour-income definition and the opening jump</summary><p>The opening income account now includes the production-tax coverage used in subsequent years. In the published 1.25 default US example, that missing coverage explained about 2.55 points of a 3.44 point opening labour-share jump. Correcting the denominator does not change wages or GDP. Remaining movements reflect model payroll, hours and value-added dynamics.</p><p>PWT labour-share method: <strong>${esc(i.method)}</strong>; source status: <strong>${esc(i.status)}</strong>. PWT includes estimated self-employment income and uses a basic-price denominator. It is a labour-income/payroll scale proxy here, not directly observed employee wages or the displayed factor-cost share. China's constant/interpolated share is not labelled a directly observed 2023 wage statistic.</p></details>
 <details><summary>Government debt held abroad · source scope matters</summary><table><caption>2023 external government claims · % source-year GDP</caption><tbody><tr><th>Total government debt owed abroad</th><td>${n(f.totalForeignGovDebtGDP)}</td></tr><tr><th>Verified foreign government securities</th><td>${n(f.foreignGovSecuritiesGDP)}</td></tr><tr><th>Identified other external government debt</th><td>${n(f.foreignGovOtherDebtGDP)}</td></tr><tr><th>Known securities subset, where full split is missing</th><td>${n(f.governmentDebtSecuritiesKnownSubsetGDP)}</td></tr></tbody></table><p>${esc(f.mappingStatus)}.</p>${f.notes.map(x=>`<p class="small muted">${esc(x)}</p>`).join('')}<p>New foreign bond purchases are financial transactions. They do not directly improve the current account. Interest paid abroad reduces primary income. The model tracks matched changes in financial-sector external assets and government external liabilities, so national saving minus investment equals the current account and the change in acquisition-cost net foreign assets.</p><p class="small muted">The current account does not uniquely determine government financing. A surplus can coexist with foreign-held public debt. Investor participation uses source ownership as a flow proxy plus an unestimated response to returns, currency and lagged external risk. New bonds are in domestic currency. Secondary-market trading, complete national IIP coverage and foreign capital-account transfers are not modelled; valuation is separate from transactions.</p><a href="${esc(f.url)}" target="_blank" rel="noreferrer">Government-holder source ↗</a></details>
 <p><a href="./data/retirement_ages_2023.json" download>Pension references ↓</a> · <a href="./data/age_cohorts_2023.json" download>Age profiles ↓</a> · <a href="./data/foreign_sovereign_2023.json" download>External public-debt coverage ↓</a> · <a href="./data/revision126_validation.json" download>Executed comparisons and remaining weaknesses ↓</a></p></section>`;
}
export function renderRevision126Outcomes(result,run,row,code){const target=document.getElementById('revision126-outcomes');if(!target)return;const openStates=[...target.querySelectorAll('details')].map(x=>x.open),open=i=>openStates[i]?'open':'';const d=growthDiagnostics(run),b=REVISION126_SOURCES[code],g=d.largestDrawdown,l=d.incomeTransition;
 const componentNames={consumption:'Household consumption',government:'Government consumption',fixedInvestment:'Fixed investment',inventories:'Inventory accumulation',netExports:'Net exports'};
 target.innerHTML=`<details class="public-budget-reference" ${open(0)}><summary>Population, working age and pension eligibility · year ${row.t}</summary><table><caption>Population composition · shares change over time</caption><tbody><tr><th>Total population</th><td>${n(row.populationMillions)} million</td></tr><tr><th>Children under 15</th><td>${n(100*row.childPopulation/row.populationIndex)}%</td></tr><tr><th>People aged 15–64</th><td>${n(row.workingAgeShare)}%</td></tr><tr><th>People aged 65+</th><td>${n(100*row.olderPopulation/row.populationIndex)}%</td></tr><tr><th>People at/above pension eligibility age · overlapping memo</th><td>${n(row.pensionEligibleShare)}%</td></tr><tr><th>Pension eligibility threshold</th><td>${n(row.retirementAge)} years</td></tr><tr><th>Labour-force participation ·15–64</th><td>${n(row.participationRate)}%</td></tr><tr><th>Labour force, opening = 100</th><td>${n(row.laborForce)}</td></tr></tbody></table><p class="small muted">The first three age groups sum to 100%. Pension eligibility is an overlapping policy measure. Statistical working age is 15–64. Age-specific participation and observed older-age activity are reweighted as the population changes. Future within-band activity rates are held fixed as a composition-only assumption; a separate pension-reform response is unestimated; eligibility does not force everyone out of work. ${b?'Country reference: '+esc(b.retirement.representativeMethod):''}</p><p class="small muted">Public pension funding is a reporting allocation of final collected worker taxes after all fiscal adjustments. It is not a separate pension fund or an observed statutory contribution rate; allocating these receipts never charges another tax. ${row.initialObservation?'The opening source observation has no simulated annual pension-payment flow.':'This row reports simulated annual flows, including when settling was run before year 0.'}</p>${retirementComparisonHTML(result,row.t)}<p><a href="./data/revision1301_validation.json" download>Retirement and pension audit · all 30 presets</a> · <a href="https://www.oecd.org/en/publications/is-it-worth-raising-the-normal-retirement-age_5f2a3b40-en.html" target="_blank" rel="noreferrer">Evidence on retirement and employment</a></p><button class="button secondary" data-price-metric="workingAgeShare">Chart working-age share ↑</button><button class="button secondary" data-price-metric="participationRate">Chart participation</button><button class="button secondary" data-price-metric="pensionEligibleShare">Chart pension-age share ↑</button></details>
 <details class="public-budget-reference" ${open(1)}><summary>Why does GDP or the labour share change?</summary><p><strong>Opening labour share:</strong> ${n(l?.from)}% → ${n(l?.to)}% in year 1. Payroll changes contribute ${n(l?.payrollEffect)} points; the factor-income denominator contributes ${n(l?.denominatorEffect)} points. These are model calculations, not observed next-year wages.</p>${g?`<p><strong>Largest GDP decline across this full run:</strong> year ${g.peakYear} to year ${g.troughYear}, ${n(g.percent)}%. The spending decomposition below adds exactly to the output change.</p><table><caption>Change from the peak · real units</caption><tbody>${Object.entries(g.components).map(([k,v])=>`<tr><th>${componentNames[k]}</th><td>${n(v)}</td></tr>`).join('')}<tr><th>Total real GDP change</th><td>${n(g.change)}</td></tr></tbody></table><p>During that interval, firm technology changed ${n(g.technologyChange)}%, paid hours ${n(g.hoursChange)}%, and capacity use ${n(g.utilizationChange)} points. Higher technology can coexist with lower sales, investment and employment.</p>`:'<p>No peak-to-later-year GDP decline occurred in this seed.</p>'}<p class="small muted">Inventory adjustment can produce a short fall; sustained weak consumption, investment, labour supply or financing can produce longer declines. These co-movements describe the simulation. They do not establish a normal or empirically validated business cycle. Weak long-run paths remain visible and the response rules remain unestimated.</p></details>
 <details class="public-budget-reference" ${open(2)}><summary>Government borrowing abroad · year ${row.t}</summary><table><caption>Represented foreign public claims · nominal units</caption><tbody>${[['Government debt held abroad',row.initialObservation&&row.foreignGovOpeningKnown===0?null:row.foreignHeldGovernmentDebt],['Identified foreign-held government bonds',row.foreignHeldGovernmentBonds],['Other identified external government debt',row.foreignHeldGovernmentOtherDebt],['External government debt with unallocated instrument',row.foreignHeldGovernmentUnallocatedDebt],['New public bonds bought abroad',row.initialObservation?null:row.foreignGovBondPurchases],[row.initialObservation?'Opening annual coupon proxy · not paid again':'Government interest paid abroad',row.governmentInterestToForeign],['Bond principal repaid abroad',row.initialObservation?null:row.publicBondRedemptionsToForeign]].map(([k,v])=>`<tr><th>${k}</th><td>${n(v)}</td></tr>`).join('')}</tbody></table><p class="small muted">Missing source coverage is not evidence of zero debt. Opening external stocks are not current-account flows. The source-year residual foreign-income channel is rebased when sovereign coupons are made explicit, preventing their double counting. New issues and principal repayments change both claims and settlement assets; interest enters the current account. This remains a partial international balance sheet.</p></details>`;
}
